"""Write docs/TEST_RESULTS.md from the last runs: tests.results in mandamul_test (scripts/db-test.sh)
and tests/e2e/results.json (tests/e2e/app_workflows.py). Run both suites first."""
import json, os, subprocess, datetime, collections
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
host, port = os.environ.get('PGHOST', '/tmp'), os.environ.get('PGPORT', '5544')
rows = subprocess.run(['psql', '-h', host, '-p', port, '-U', 'postgres', '-d', 'mandamul_test', '-At', '-F', '\t', '-c',
                       'select workflow, name, ok, coalesce(detail, \'\') from tests.results order by n'], capture_output=True, text=True, check=True).stdout
db = [dict(zip(['workflow', 'name', 'ok', 'detail'], l.split('\t'))) for l in rows.strip().split('\n') if l]
for r in db: r['ok'] = r['ok'] == 't'
bk = open(os.path.join(root, 'tests/last-backup-check.txt')).read().strip()
e2e = json.load(open(os.path.join(root, 'tests/e2e/results.json')))
app_e2e = json.load(open(os.path.join(root, 'app/tests/e2e/results.json')))
unit = subprocess.run([os.environ.get('BUN', 'bun'), 'test', 'tests/unit'], cwd=os.path.join(root, 'app'), capture_output=True, text=True)
unit_line = next((l.strip() for l in (unit.stdout + unit.stderr).split('\n') if l.strip().startswith('Ran ')), 'not run')
unit_pass = next((l.strip() for l in (unit.stdout + unit.stderr).split('\n') if l.strip().endswith(' pass')), '')
def table(rs):
    g = collections.OrderedDict()
    for r in rs: g.setdefault(r['workflow'], []).append(r)
    out = ['| Group | Passed | Failed |', '|---|---|---|']
    out += [f"| {w} | {sum(x['ok'] for x in v)} | {sum(not x['ok'] for x in v)} |" for w, v in g.items()]
    out.append(f"| **Total** | **{sum(r['ok'] for r in rs)}** | **{sum(not r['ok'] for r in rs)}** |")
    detail = []
    for w, v in g.items():
        detail.append(f"\n**{w}**\n")
        detail += [f"- {'PASS' if x['ok'] else '**FAIL**'} — {x['name']}" for x in v]
    return out, detail
dt, dd = table(db); et, ed = table(e2e); at, ad = table(app_e2e)
md = [f"# Test results", "", f"Run on {datetime.date.today():%d %b %Y}. Generated by `scripts/test-report.py` from the actual runs; nothing here is typed by hand.", "",
      "## What was run, and where", "",
      f"- **Database suite** (`scripts/db-test.sh`): PostgreSQL 16 with a local stub of Supabase's `auth` and `storage` schemas. All {len([f for f in os.listdir(os.path.join(root, 'supabase/migrations')) if f.endswith('.sql')])} migrations applied from empty, then the 12 business workflows, the security, automation and storage checks, the Phase 3 batches and a 20-villa synthetic resort lifecycle (labelled SYNTHETIC TEST DATA) executed as real users through the `api` functions under row-level security. Followed by a backup (`pg_dump`) and restore (`pg_restore`) into a fresh database with row counts compared.",
      "- **Browser suite** (`tests/e2e/app_workflows.py`): headless Chrome driving the prototype screens — sign-in, clicks and form entry as different users — through the same 12 workflows, the negative cases and the Phase 3 screens (action center, digital twin, financial intelligence, contractor scores, procurement planning, executive reports, AI questions, mobile drafting).",
      "- **Permission match** (`tests/consistency/permissions_match.py`): the prototype's role matrix compared grant by grant with the database defaults.",
      "- **Production application** (`app/`): unit tests (`bun test`), TypeScript type check, production build, and a browser run (`app/tests/e2e/app_production.py`) of the built application against the real database through `app/dev/gateway.ts`, a LOCAL-ONLY stand-in for Supabase's PostgREST RPC and Auth endpoints (password sign-in, TOTP enrolment and verification raising the session to aal2).", "",
      "## Not verified", "",
      "- Nothing has been deployed: no hosted Supabase project, no Vercel deployment, no GitHub Actions run.",
      "- Supabase-specific behaviour (PostgREST exposure of `api`, real Auth/MFA, Storage API limits, pg_cron) — the stub only imitates the parts the SQL depends on. pg_cron was not available locally, so the scheduler block was skipped.",
      "- Email and WhatsApp delivery — no provider is connected; the tests only prove these are recorded as *not configured* and never as sent.",
      "- The AI assistant with the live model — it runs only inside claude.ai after the viewer allows it; the tests cover the fallback when it is unavailable.",
      "- The production application against hosted Supabase and Vercel: the staging project exists (19 Nov 2026) but the schema has not been pushed and nothing is deployed; the browser run used the local gateway, not real PostgREST or Supabase Auth.",
      "- Hosted PostgreSQL is version 17; every run here used PostgreSQL 16.",
      "- Performance on real data and real network: the timings in `docs/perf/` are on synthetic volume on the build machine.",
      "- Offline capture on real phones and poor networks — the prototype keeps drafts on the device; no service worker exists.", "",
      "## Database suite", ""] + dt + ["", f"Backup / restore check: `{bk}` — row counts of the business tables before the dump and after the restore."] + dd + \
     ["", "## Browser suite (prototype)", ""] + et + ed + \
     ["", "## Production application", "", f"Unit tests: {unit_pass} — {unit_line}", "", "Browser run on the real database:", ""] + at + ad + [""]
open(os.path.join(root, 'docs/TEST_RESULTS.md'), 'w').write('\n'.join(md))
print(f"database {sum(r['ok'] for r in db)}/{len(db)} · prototype e2e {sum(r['ok'] for r in e2e)}/{len(e2e)} · app e2e {sum(r['ok'] for r in app_e2e)}/{len(app_e2e)} · unit {unit_pass}")
